//! WinUI 3 (Windows App SDK) projection for the Mailin Windows front-end.
//!
//! `windows` 0.62 has no XAML namespaces: the Windows App SDK metadata is not
//! part of the Windows SDK, so `Microsoft.UI.Xaml` and friends have to be
//! projected separately. The bindings in `src/bindings.rs` are generated by
//! `cargo xtask winui-bindgen` from the `.winmd` files that ship in the
//! Microsoft.WindowsAppSDK, Microsoft.Web.WebView2 and
//! Microsoft.Windows.SDK.Contracts NuGet packages.
//!
//! The projection is deliberately narrow: it contains the application, window,
//! layout and text controls, the common input controls and WebView2 instead of
//! the ~43 MB full XAML namespace. The filter lives in `filter.txt` next to this
//! crate and is the input to the generator, so regenerating the bindings is
//! reproducible.
//!
//! The generated code is not edited by hand.

#![cfg(windows)]
#![allow(
    non_snake_case,
    non_camel_case_types,
    non_upper_case_globals,
    clippy::all
)]

#[rustfmt::skip]
mod bindings;

pub use bindings::*;
